const w = 800;
const h = 800;
let rectWidth = 400;
let rectNum = 40;

let palette = [];

window.setup = function () {
  createCanvas(w, h, WEBGL);
  palette = colorArray[1].colors;
  frameRate(30);
  background(palette[0]);
  strokeWeight(1);
  noFill();
  stroke(palette[1]);
};

window.draw = function () {
  background(palette[0]);
  // orbitControl();

  rotateX(PI / 4);
  rotateZ(-PI / 4);

  push();
  drowRect(100);
  pop();
  push();
  rotateX(PI / 2);
  scale(0.5);
  drowRect(10);
  pop();
  push();
  rotateY(PI / 2);
  scale(0.2);
  drowRect(1);
  pop();
  // // noLoop() removed for animation
};

function drowRect(s) {
  noiseSeed(s);
  for (let i = 0; i < rectNum; i++) {
    push();

    let f = sin((frameCount * speedMult) / 50 + noise(0.05 * i)) * PI;
    let easedValue = easeInOutCubic(f / PI);
    rotateZ(easedValue);
    translate(-rectWidth / 2, -rectWidth / 2, (rectNum * 10) / 2 - 10 * i);
    rect(0, 0, rectWidth, rectWidth);
    pop();
  }
}

function easeInOutCubic(t) {
  return t < 0.5 ? 4.0 * t * t * t : 0.5 * pow(2.0 * t - 2.0, 3.0) + 1.0;
}

const colorArray = [
  {
    colors: ["#000000", "#dfe2e4", "#54585f"],
  },
  {
    colors: ["#dfdad3", "#253276", "#000000"],
  },
